CREATE DATABASE IF NOT EXISTS dataflow360 CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE dataflow360;

CREATE TABLE users (id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role ENUM('ADMIN','ANALYST','VIEWER') NOT NULL DEFAULT 'VIEWER',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE bronze_customers (id INT PRIMARY KEY AUTO_INCREMENT,customer_name VARCHAR(120),email VARCHAR(190),phone VARCHAR(40),city VARCHAR(100),source_ref VARCHAR(50),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_bronze_customer_email(email));
CREATE TABLE bronze_products (id INT PRIMARY KEY AUTO_INCREMENT,product_name VARCHAR(150),category VARCHAR(100),unit_price DECIMAL(12,2),source_ref VARCHAR(50),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_bronze_product_name(product_name));
CREATE TABLE bronze_orders (id INT PRIMARY KEY AUTO_INCREMENT,customer_email VARCHAR(190),product_name VARCHAR(150),quantity VARCHAR(20),order_date VARCHAR(40),amount DECIMAL(12,2),source_ref VARCHAR(50),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_bronze_order_email(customer_email));
CREATE TABLE silver_customers (id INT PRIMARY KEY AUTO_INCREMENT,customer_name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,phone VARCHAR(40) NOT NULL,city VARCHAR(100) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE silver_products (id INT PRIMARY KEY AUTO_INCREMENT,product_name VARCHAR(150) NOT NULL,category VARCHAR(100) NOT NULL,unit_price DECIMAL(12,2) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_silver_product(product_name));
CREATE TABLE silver_orders (id INT PRIMARY KEY AUTO_INCREMENT,customer_id INT NOT NULL,product_id INT NOT NULL,quantity INT NOT NULL,order_date DATE NOT NULL,amount DECIMAL(12,2) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES silver_customers(id),FOREIGN KEY(product_id) REFERENCES silver_products(id),INDEX idx_silver_order_date(order_date));
CREATE TABLE gold_daily_sales (id INT PRIMARY KEY AUTO_INCREMENT,sales_date DATE NOT NULL UNIQUE,revenue DECIMAL(14,2) NOT NULL,order_count INT NOT NULL,units_sold INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE gold_monthly_revenue (id INT PRIMARY KEY AUTO_INCREMENT,month DATE NOT NULL UNIQUE,revenue DECIMAL(14,2) NOT NULL,order_count INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE gold_customer_summary (id INT PRIMARY KEY AUTO_INCREMENT,customer_id INT NOT NULL UNIQUE,customer_name VARCHAR(120) NOT NULL,total_orders INT NOT NULL,total_spent DECIMAL(14,2) NOT NULL,customer_segment VARCHAR(30) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES silver_customers(id));
CREATE TABLE gold_product_performance (id INT PRIMARY KEY AUTO_INCREMENT,product_id INT NOT NULL UNIQUE,product_name VARCHAR(150) NOT NULL,category VARCHAR(100) NOT NULL,units_sold INT NOT NULL,revenue DECIMAL(14,2) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(product_id) REFERENCES silver_products(id));
CREATE TABLE gold_city_sales (id INT PRIMARY KEY AUTO_INCREMENT,city VARCHAR(100) NOT NULL UNIQUE,revenue DECIMAL(14,2) NOT NULL,order_count INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE etl_jobs (id INT PRIMARY KEY AUTO_INCREMENT,status ENUM('RUNNING','SUCCESS','FAILED') NOT NULL,started_at DATETIME NOT NULL,ended_at DATETIME NULL,duration_ms BIGINT NULL,records_processed INT NOT NULL DEFAULT 0,error_message TEXT NULL,triggered_by INT NULL,FOREIGN KEY(triggered_by) REFERENCES users(id),INDEX idx_etl_status_started(status,started_at));
CREATE TABLE etl_logs (id INT PRIMARY KEY AUTO_INCREMENT,job_id INT NOT NULL,level ENUM('INFO','WARN','ERROR') NOT NULL,message TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(job_id) REFERENCES etl_jobs(id) ON DELETE CASCADE,INDEX idx_log_job(job_id));
CREATE TABLE data_quality_rules (id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL,rule_type VARCHAR(50) NOT NULL,table_name VARCHAR(100) NOT NULL,column_name VARCHAR(100),is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE data_quality_results (id INT PRIMARY KEY AUTO_INCREMENT,completeness DECIMAL(5,2) NOT NULL,accuracy DECIMAL(5,2) NOT NULL,consistency DECIMAL(5,2) NOT NULL,uniqueness_score DECIMAL(5,2) NOT NULL,validity DECIMAL(5,2) NOT NULL,overall_score DECIMAL(5,2) NOT NULL,run_by INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(run_by) REFERENCES users(id));
CREATE TABLE saved_queries (id INT PRIMARY KEY AUTO_INCREMENT,user_id INT NOT NULL,name VARCHAR(150) NOT NULL,query_text TEXT NOT NULL,is_public BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE query_history (id INT PRIMARY KEY AUTO_INCREMENT,user_id INT NOT NULL,query_text TEXT NOT NULL,rows_returned INT NOT NULL DEFAULT 0,execution_ms INT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX idx_history_user_date(user_id,created_at));
CREATE TABLE csv_datasets (id INT PRIMARY KEY AUTO_INCREMENT,file_name VARCHAR(255) NOT NULL,headers JSON NOT NULL,row_count INT NOT NULL,quality_score DECIMAL(5,2) NOT NULL,uploaded_by INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(uploaded_by) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE csv_dataset_rows (id BIGINT PRIMARY KEY AUTO_INCREMENT,dataset_id INT NOT NULL,row_number INT NOT NULL,row_data JSON NOT NULL,FOREIGN KEY(dataset_id) REFERENCES csv_datasets(id) ON DELETE CASCADE,INDEX idx_csv_dataset_row(dataset_id,row_number));
CREATE TABLE bronze_csv_records (id BIGINT PRIMARY KEY AUTO_INCREMENT,dataset_id INT NOT NULL,row_number INT NOT NULL,row_data JSON NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(dataset_id) REFERENCES csv_datasets(id) ON DELETE CASCADE,INDEX idx_bronze_csv_dataset(dataset_id,row_number));
CREATE TABLE silver_csv_records (id BIGINT PRIMARY KEY AUTO_INCREMENT,dataset_id INT NOT NULL,row_number INT NOT NULL,row_data JSON NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(dataset_id) REFERENCES csv_datasets(id) ON DELETE CASCADE,INDEX idx_silver_csv_dataset(dataset_id,row_number));
CREATE TABLE gold_csv_dataset_summary (id INT PRIMARY KEY AUTO_INCREMENT,dataset_id INT NOT NULL UNIQUE,file_name VARCHAR(255) NOT NULL,total_rows INT NOT NULL,clean_rows INT NOT NULL,duplicate_rows INT NOT NULL,null_cells INT NOT NULL,quality_score DECIMAL(5,2) NOT NULL,processed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(dataset_id) REFERENCES csv_datasets(id) ON DELETE CASCADE);

